<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function showLogin(){return view('auth.login');} public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']); if(Auth::attempt($data,$r->boolean('remember'))){$r->session()->regenerate(); return redirect()->intended('/dashboard');} return back()->withErrors(['email'=>'Invalid credentials.'])->withInput($r->only('email'));} public function showRegister(){return view('auth.register');} public function register(Request $r){$data=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users','password'=>'required|string|min:8|confirmed']); $user=User::create([...$data,'role'=>'student']); Auth::login($user); $r->session()->regenerate(); return redirect('/dashboard');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');} }
